"""Re-evaluate #515 on four fixed public folio blocks and matched FFT settings."""
from collections import defaultdict
import json
from pathlib import Path
from random import Random
from statistics import median
import sys

import numpy as np

from voynich_spectral_geometry import within_folio_slices
from voynich_spectral_lines import (
    FOLIO, GLYPH_ID, Spectrum, aligned_corpus, bins_for, corpus, flat,
    shuffle_folio_interiors, shuffle_line_interiors,
)

PERIOD = 44
PERMUTATIONS = 99
GLYPHS = np.array([ord(char) for char in GLYPH_ID], dtype=np.uint8)


class WindowSpectrum:
    def __init__(self, rows, block, no_crossing=False):
        glyphs = sum(len(line) for _, line in rows)
        regions = within_folio_slices(rows, block) if no_crossing else (slice(0, glyphs),)
        starts = [i for region in regions for i in range(region.start, region.stop - block + 1, block)]
        self.positions = np.asarray(starts, dtype=int)[:, None] + np.arange(block)
        self.taper = 0.5 - 0.5 * np.cos(2 * np.pi * np.arange(block) / block)
        self.energy = (self.taper * self.taper).sum()
        self.bins = bins_for(PERIOD, block)
        self.periods = {name: min(self.bins['center'], key=lambda k: (abs(block / k - PERIOD * factor), k))
                        for name, factor in (('nearest_shorter', .95), ('nearest', 1.), ('nearest_longer', 1.05))}
        self.block = block

    def power(self, text):
        glyphs = np.frombuffer(text.encode('ascii'), dtype=np.uint8)[self.positions]
        one_hot = glyphs[:, None, :] == GLYPHS[None, :, None]
        fft = np.fft.rfft(one_hot * self.taper[None, None, :], axis=-1)
        return np.square(np.abs(fft)).sum(axis=1).mean(axis=0) / self.energy

    def ratios(self, power):
        shoulders = np.mean([power[list(self.bins[band])].mean() for band in ('short', 'long')])
        center = power[list(self.bins['center'])]
        return {'wide': float(center.mean() / shoulders), 'max_center': float(center.max() / shoulders),
                **{name: float(power[k] / shoulders) for name, k in self.periods.items()}}


def exact_prefix_slots(rows, block):
    active = {i for s in within_folio_slices(rows, block) for i in range(s.start, s.stop)}
    groups = defaultdict(list)
    offset = 0
    for folio, line in rows:
        groups[folio].extend(i for i in range(offset + 1, offset + len(line) - 1) if i in active)
        offset += len(line)
    return groups


def prefix_shuffle(text, groups, rng):
    sequence = list(text)
    for indices in groups.values():
        values = [text[i] for i in indices]
        rng.shuffle(values)
        for index, value in zip(indices, values, strict=True):
            sequence[index] = value
    return ''.join(sequence)


def upper_tail(observed, draws):
    return {key: {'p_upper': (1 + sum(sample[key] >= value - 1e-12 for sample in draws)) / (len(draws) + 1),
                  'null_median': median(sample[key] for sample in draws)}
            for key,value in observed.items()}


def audit_group(rows):
    spectra = {name: WindowSpectrum(rows, size, in_folio) for name,size,in_folio in
               [('continuous_1024', 1024, False), ('continuous_512', 512, False), ('within_folio_512', 512, True)]}
    spectra = {name: spectrum for name,spectrum in spectra.items() if len(spectrum.positions)}
    observed_text = flat(rows)
    observed = {name: spectrum.ratios(spectrum.power(observed_text)) for name,spectrum in spectra.items()}
    results = {name: {'windows': len(spectrum.positions), 'used_glyphs': len(spectrum.positions) * spectrum.block,
                      'periods': {probe: spectrum.block / k for probe,k in spectrum.periods.items()},
                      'observed': observed[name], 'nulls':{}} for name,spectrum in spectra.items()}
    for null, func, seed in [('folio_interiors',shuffle_folio_interiors,692615),
                             ('line_interiors',shuffle_line_interiors,693615)]:
        rng = Random(seed)
        draws = defaultdict(list)
        for _ in range(PERMUTATIONS):
            shuffled = func(rows,rng)
            for name,spectrum in spectra.items():
                draws[name].append(spectrum.ratios(spectrum.power(shuffled)))
        for name, samples in draws.items():
            results[name]['nulls'][null] = upper_tail(observed[name], samples)
    if 'within_folio_512' in spectra:
        spectrum = spectra['within_folio_512']
        slots = exact_prefix_slots(rows, spectrum.block)
        rng = Random(695615)
        draws = [spectrum.ratios(spectrum.power(prefix_shuffle(observed_text, slots, rng))) for _ in range(PERMUTATIONS)]
        results['within_folio_512']['nulls']['scored_prefix_folio_interiors'] = upper_tail(observed['within_folio_512'], draws)
    return {'folios': len({folio for folio,_ in rows}), 'lines': len(rows), 'glyphs': len(observed_text), 'layouts':results}


def numeric_replay(rows, block):
    old = Spectrum(PERIOD, block).band_power(flat(rows))['band_bins_power']
    new = WindowSpectrum(rows, block).power(flat(rows))
    max_absolute_error = max(abs(new[k] - value) for k,value in old.items())
    assert max_absolute_error < 1e-10
    return float(max_absolute_error)


def main():
    rows_by_partition = aligned_corpus()
    folios = list(dict.fromkeys(FOLIO.match(page.id)[0] for page in corpus.pages('zl')))
    quartile = {folio: 4 * i // len(folios)  for i,folio in enumerate(folios)}
    replay = {}
    results = {}
    for partition, editions in rows_by_partition.items():
        replay[partition] = {edition:{str(block): numeric_replay(rows, block) for block in (512, 1024)}
                             for edition,rows in editions.items()}
        results[partition] = {}
        for block in range(4):
            results[partition][str(block+1)] = {}
            for edition, rows in editions.items():
                subgroup = [(folio, line) for folio,line in rows if quartile[folio] == block]
                results[partition][str(block+1)][edition] = audit_group(subgroup)
                print(f'{partition} {block+1} {edition} complete', file=sys.stderr, flush=True)
    print(json.dumps({'center':PERIOD,'permutations':PERMUTATIONS,'max_errors':replay,'results':results}, indent=2))


if __name__ == '__main__':
    main()
